from dataclasses import dataclass, field
from typing import Any


SCORE_VERSION = "prototype-score-v0.2"
PROTOTYPE_DISCLAIMER = (
    "This score is generated by an early research prototype. It is not a medical "
    "diagnosis or a professional mental-health assessment."
)
INSUFFICIENT_DATA_MESSAGE = "Insufficient interaction data for a meaningful prototype score."
PROTOTYPE_DISCLAIMER_ZH_CN = (
    "该分数由早期研究原型生成，不是医学诊断或专业心理健康评估。"
)
INSUFFICIENT_DATA_MESSAGE_ZH_CN = "互动数据不足，无法生成有意义的原型分数。"


@dataclass(frozen=True)
class ScoringConfig:
    min_post_views: int = 3
    min_comments: int = 1
    min_interactions: int = 3
    weights: dict[str, float] = field(
        default_factory=lambda: {
            "negative_word_ratio": 0.25,
            "self_reference_ratio": 0.15,
            "low_engagement": 0.25,
            "skip_rate": 0.2,
            "long_latency": 0.15,
        }
    )


class PrototypeScorer:
    def __init__(self, config: ScoringConfig | None = None):
        self.config = config or ScoringConfig()

    def score(self, features: dict[str, Any], language: str = "en") -> dict[str, Any]:
        behavior = features["behavior_features"]
        text = features["text_features"]
        data_quality = features["data_quality"]
        has_sufficient_data = self._has_sufficient_data(behavior, data_quality)
        is_chinese = language == "zh-CN"

        if not has_sufficient_data:
            return {
                "prototype_score": 0.0,
                "prototype_signal_label": "数据不足" if is_chinese else "Insufficient data",
                "prototype_signal_description": (
                    "互动数据不足，无法划分原型情绪信号类别。"
                    if is_chinese
                    else "There is not enough interaction data to assign a prototype emotional-signal category."
                ),
                "score_version": SCORE_VERSION,
                "score_breakdown": {},
                "has_sufficient_data": False,
                "disclaimer": (
                    PROTOTYPE_DISCLAIMER_ZH_CN if is_chinese else PROTOTYPE_DISCLAIMER
                ),
                "summary": (
                    INSUFFICIENT_DATA_MESSAGE_ZH_CN
                    if is_chinese
                    else INSUFFICIENT_DATA_MESSAGE
                ),
            }

        components = {
            "negative_word_ratio": min(text["negative_word_ratio"], 1),
            "self_reference_ratio": min(text["self_reference_ratio"], 1),
            "low_engagement": max(0, 1 - min(behavior["engagement_rate"], 1)),
            "skip_rate": min(behavior["skip_rate"], 1),
            "long_latency": min(behavior["average_response_latency_ms"] / 30000, 1),
        }
        weighted = {
            key: round(value * self.config.weights[key] * 100, 2)
            for key, value in components.items()
        }
        prototype_score = round(min(max(sum(weighted.values()), 0), 100), 2)
        signal = _score_to_signal(prototype_score, language)

        return {
            "prototype_score": prototype_score,
            "prototype_signal_label": signal["label"],
            "prototype_signal_description": signal["description"],
            "score_version": SCORE_VERSION,
            "score_breakdown": {
                "components": components,
                "weighted_points": weighted,
                "minimum_data_requirements": {
                    "min_post_views": self.config.min_post_views,
                    "min_comments": self.config.min_comments,
                    "min_interactions": self.config.min_interactions,
                },
            },
            "has_sufficient_data": True,
            "disclaimer": (
                PROTOTYPE_DISCLAIMER_ZH_CN if is_chinese else PROTOTYPE_DISCLAIMER
            ),
            "summary": (
                "原型分数根据提取的行为、文本和时间特征计算，请勿将其解读为临床结果。"
                if is_chinese
                else (
                    "Prototype score calculated from extracted behavior, text, and timing features. "
                    "Do not interpret it as a clinical result."
                )
            ),
        }

    def _has_sufficient_data(self, behavior: dict[str, Any], data_quality: dict[str, Any]) -> bool:
        return (
            data_quality["interaction_count"] >= self.config.min_interactions
            and behavior["post_view_count"] >= self.config.min_post_views
            and behavior["comment_count"] >= self.config.min_comments
        )


def _score_to_signal(score: float, language: str = "en") -> dict[str, str]:
    if language == "zh-CN":
        if score < 25:
            return {
                "label": "较低的原型信号",
                "description": "本次会话呈现的原型情绪压力信号相对较少。",
            }
        if score < 50:
            return {
                "label": "轻微的原型压力",
                "description": "本次会话呈现出一些可能反映轻微情绪压力的原型信号。",
            }
        if score < 75:
            return {
                "label": "较明显的原型压力",
                "description": "本次会话呈现出较为明显的原型情绪压力信号。",
            }
        return {
            "label": "较强的原型压力",
            "description": "在本演示模型中，本次会话呈现出较强的原型情绪压力信号。",
        }

    if score < 25:
        return {
            "label": "Low prototype signal",
            "description": "This session shows relatively few prototype emotional-strain signals.",
        }
    if score < 50:
        return {
            "label": "Mild prototype strain",
            "description": "This session shows some prototype signals that may reflect mild emotional strain.",
        }
    if score < 75:
        return {
            "label": "Noticeable prototype strain",
            "description": "This session shows more noticeable prototype emotional-strain signals.",
        }
    return {
        "label": "Strong prototype strain",
        "description": "This session shows stronger prototype emotional-strain signals within this demo model.",
    }


def calculate_risk_score(text_features: dict, behavior_features: dict) -> dict:
    """Backward-compatible wrapper for older code paths.

    v0.2 uses PrototypeScorer and does not expose clinical risk categories.
    """
    score = PrototypeScorer().score(
        {
            "behavior_features": {
                "post_view_count": behavior_features.get("total_interactions", 0),
                "comment_count": behavior_features.get("comment_count", 0),
                "engagement_rate": behavior_features.get("engagement_score", 0),
                "skip_rate": behavior_features.get("skip_rate", 0),
                "average_response_latency_ms": 0,
            },
            "text_features": {
                "negative_word_ratio": min(text_features.get("negative_count", 0) / 10, 1),
                "self_reference_ratio": min(text_features.get("self_ref_count", 0) / 20, 1),
            },
            "data_quality": {
                "interaction_count": behavior_features.get("total_interactions", 0),
            },
        }
    )
    return {
        "risk_score": round(score["prototype_score"] / 100, 2),
        "risk_level": "prototype",
    }
